-- An Enrollment keeps the source id of the Event whose Trigger began it, or the Rule Firing whose
-- Enroll Action made it, and one of each enrolls a Contact in an Automation once; an entry the
-- entry checks refuse is a skipped entry (ADR 0127). ent's diff wrote the DDL; it is split by hand:
-- the previous migration (20261122153351) builds the Firing's unique key, this one adds the columns,
-- the constraints of the live automation_runs NOT VALID and the new table with its indexes, and the
-- next one (20261122153353) validates the constraints and builds the indexes of automation_runs
-- concurrently.
ALTER TABLE "automation_runs" ADD COLUMN "trigger_source_id" character varying NULL, ADD COLUMN "firing_id" bigint NULL;
ALTER TABLE "automation_runs" ADD CONSTRAINT "automation_runs_entry_check" CHECK ((trigger_source_id IS NULL) OR (firing_id IS NULL)) NOT VALID;
ALTER TABLE "automation_runs" ADD CONSTRAINT "automation_runs_rule_firings_firing" FOREIGN KEY ("workspace_id", "firing_id") REFERENCES "rule_firings" ("workspace_id", "id") ON UPDATE NO ACTION ON DELETE SET NULL (firing_id) NOT VALID;
CREATE TABLE "automation_skipped_entries" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "source_id" character varying NULL, "reason" character varying NOT NULL, "occurred_at" timestamptz NOT NULL, "automation_id" bigint NOT NULL, "contact_id" bigint NOT NULL, "firing_id" bigint NULL, "workspace_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "automation_skipped_entries_automations_automation" FOREIGN KEY ("workspace_id", "automation_id") REFERENCES "automations" ("workspace_id", "id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "automation_skipped_entries_contacts_contact" FOREIGN KEY ("workspace_id", "contact_id") REFERENCES "contacts" ("workspace_id", "id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "automation_skipped_entries_rule_firings_firing" FOREIGN KEY ("workspace_id", "firing_id") REFERENCES "rule_firings" ("workspace_id", "id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "automation_skipped_entries_wor_2b4c33249723dfa36dc3aabcb0258048" FOREIGN KEY ("workspace_id") REFERENCES "workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "automation_skipped_entries_entry_check" CHECK ((source_id IS NULL) OR (firing_id IS NULL)), CONSTRAINT "automation_skipped_entries_reason_check" CHECK ((reason)::text = ANY ((ARRAY['active_enrollment'::character varying, 'once'::character varying])::text[])));
CREATE UNIQUE INDEX "automation_skipped_entries_workspace_automation_firing" ON "automation_skipped_entries" ("workspace_id", "automation_id", "firing_id");
