CREATE INDEX "automationskippedentry_workspace_id_automation_id_occurred_at" ON "automation_skipped_entries" ("workspace_id", "automation_id", "occurred_at");
CREATE INDEX "automationskippedentry_workspace_id_contact_id" ON "automation_skipped_entries" ("workspace_id", "contact_id");
